    let chiaveSugliOrdini = createdOrderIds.length < 2;
    if (createdOrderIds.length > 1) {
      const { error: errChiaveOrdini } = await admin.from('orders').update({ carrello_contanti: chiaveCarrello }).in('id', createdOrderIds).eq('user_id', user.id);
      chiaveSugliOrdini = !errChiaveOrdini;
      if (errChiaveOrdini) logger.warn('[cod] chiave del carrello non scritta sugli ordini', { chiave: chiaveCarrello, ordini: createdOrderIds, message: errChiaveOrdini.message });
    }
    const avvisaCarrelloSenzaRiga = (chiave: string | null) => createdOrderIds.length < 2 ? Promise.resolve() : notifyAdmins('⚠️ Carrello in contanti senza la sua riga', `Gli ordini ${createdOrderIds.map((id) => `#${id.slice(0, 6).toUpperCase()}`).join(', ')} sono nati insieme, ma la riga del loro carrello non si è scritta: ${chiaveSugliOrdini ? 'il carrello si ritrova comunque dalla chiave scritta sugli ordini.' : 'se un negozio rifiuta, la consegna degli altri non si rifà da sola: guardali tu.'}`, '/admin/orders').then(() => undefined).catch((err) => logger.error('[cod] avviso agli amministratori non partito', { chiave, err }));`. (B) Dentro `if (errChiave) {` (riga 1930), dopo la chiusura del `logger.error('[cod] prova del tentativo NON scritta…', {…});` (riga 1937): `await avvisaCarrelloSenzaRiga(chiaveTentativo);`. (C) Dentro `if (errCarrello) {` (riga 1950), dopo il `logger.warn(…)`: `await avvisaCarrelloSenzaRiga(chiaveCarrello);`. notifyAdmins è già importato (riga 39). CONDIZIONE (revisore): la chiave scritta sugli ordini è chiaveCarrello dopo il cambio di generazione (`chiave~N`, righe ~457-458) o il `cod-<uuid>`, su tutti gli ordini dello stesso invio; MAI l'intestazione idempotency-key così com'è: dopo 12 ore due carrelli diversi avrebbero la stessa chiave e la ricerca li unirebbe.

