+   13, 1300, 'cod', 'PENDING', 'NEW', 100, 100, 'Maria', '333', 'Via A 1', 'Piacenza', '29121'),
+  ('e6400000-0000-0000-0000-0000000000a3', 'e6400000-0000-0000-0000-000000000003', 'e6400000-0000-0000-0000-000000000002',
